template:
use std::io::{Result, Write};

fn write_header<W: Write>(w: ⟦slot1⟧) -> Result<()> {
    w.write_all(b"HEAD")
}

fn main() {
    let mut buf = Vec::new();
    write_header(⟦slot2⟧).unwrap();
    assert_eq!(buf, b"HEAD");
}

tests:
#[test]
fn test_write_header() {
    let mut buffer = Vec::new();
    write_header(&mut buffer).unwrap();
    assert_eq!(buffer, b"HEAD");
}
